// Generates src/lib/pixel/worldMap.ts: a 96x48 land/sea bitmap, equirectangular, 84N to 60S.
// Source: Natural Earth 110m land (public domain) via the world-atlas package (ISC).
// Run once with `pnpm world-map`; the site ships the generated file and never imports these packages.
import { readFileSync, writeFileSync } from "node:fs";
import { geoContains } from "d3-geo";
import { feature } from "topojson-client";

type Topo = Parameters<typeof feature>[0];

const COLS = 96;
const ROWS = 48;
const LAT_TOP = 84;
const LAT_BOTTOM = -60;

const topo = JSON.parse(
  readFileSync(new URL("../node_modules/world-atlas/land-110m.json", import.meta.url), "utf8"),
) as Topo;
const land = feature(topo, topo.objects.land);

const cellLon = 360 / COLS;
const cellLat = (LAT_TOP - LAT_BOTTOM) / ROWS;

const rows: string[] = [];
for (let r = 0; r < ROWS; r++) {
  const lat = LAT_TOP - (r + 0.5) * cellLat;
  let line = "";
  for (let c = 0; c < COLS; c++) {
    const lon = -180 + (c + 0.5) * cellLon;
    line += geoContains(land, [lon, lat]) ? "#" : ".";
  }
  rows.push(line);
}

const out = `// Generated by scripts/build-world-map.ts (pnpm world-map). Do not edit by hand.
// Natural Earth 110m land (public domain), sampled at each cell centre. '#' land, '.' sea.
export const WORLD_COLS = ${COLS};
export const WORLD_ROWS = ${ROWS};

export const WORLD_ROWS_DATA: string[] = [
${rows.map((r) => `  "${r}",`).join("\n")}
];

const LAT_TOP = ${LAT_TOP};
const LAT_BOTTOM = ${LAT_BOTTOM};

const clamp = (n: number, max: number) => Math.min(max, Math.max(0, n));

/** Grid cell for a coordinate. Anything outside 84N to 60S is clamped to the nearest edge row. */
export function toCell(lat: number, lon: number): { col: number; row: number } {
  const col = Math.floor(((lon + 180) / 360) * WORLD_COLS);
  const row = Math.floor(((LAT_TOP - lat) / (LAT_TOP - LAT_BOTTOM)) * WORLD_ROWS);
  return { col: clamp(col, WORLD_COLS - 1), row: clamp(row, WORLD_ROWS - 1) };
}
`;

writeFileSync(new URL("../src/lib/pixel/worldMap.ts", import.meta.url), out);
console.log(`wrote worldMap.ts: ${ROWS} rows, ${rows.join("").split("#").length - 1} land cells`);
